C=gke_tsdtechnology_us-central1-c_tsd; kubectl --context $C get deploy -A 2>&1 | grep -iE "web" | head; for d in $(kubectl --context $C get deploy -n default -o name 2>/dev/null | grep -i web | head -3); do echo "== $d"; kubectl --context $C get $d -n default -o json | python3 -c "
import json,sys
d=json.load(sys.stdin)
for c in d['spec']['template']['spec']['containers']:
  for e in c.get('env',[]):
    if any(k in e['name'] for k in ('EMAIL','SMTP','SENDGRID')): print(e['name'], e.get('value', '<from secret/configmap>'))
  for ef in c.get('envFrom',[]): print('envFrom', ef)
"; done

